#!/usr/bin/env node
// Generates src/theme/web-theme.generated.ts from the web dashboard's canonical stylesheet
// (../src/dashboard/style.css) so the mobile app uses the exact same palette, fonts and
// rendered-plan styles as the web app. Run `pnpm sync-theme` after changing the web CSS;
// test/theme.test.ts fails when the generated file is stale.
const { readFileSync, writeFileSync } = require("node:fs")
const { resolve } = require("node:path")

const SOURCE = resolve(__dirname, "../../src/dashboard/style.css")
const TARGET = resolve(__dirname, "../src/theme/web-theme.generated.ts")

// Rules the reader WebView needs: the global reset and link colours, plus everything that styles
// server-rendered plan HTML. Dashboard chrome (rail, hero, cards) is rebuilt natively instead.
const READER_SELECTOR = /^(\*|a(:hover)?$|\.markdown-body|\.pm-|span\.pm-|\.mermaid-diagram)/

function stripComments(css) {
  return css.replace(/\/\*[\s\S]*?\*\//g, "")
}

/** Splits CSS into top-level { prelude, body } blocks, respecting quoted strings. */
function blocks(css) {
  const out = []
  let depth = 0
  let quote = null
  let preludeStart = 0
  let bodyStart = 0
  let prelude = ""
  for (let index = 0; index < css.length; index++) {
    const character = css[index]
    if (quote) {
      if (character === "\\") index++
      else if (character === quote) quote = null
      continue
    }
    if (character === '"' || character === "'") quote = character
    else if (character === "{") {
      if (depth === 0) { prelude = css.slice(preludeStart, index).trim(); bodyStart = index + 1 }
      depth++
    } else if (character === "}") {
      depth--
      if (depth < 0) throw new Error("Unbalanced braces in web stylesheet")
      if (depth === 0) { out.push({ prelude, body: css.slice(bodyStart, index) }); preludeStart = index + 1 }
    } else if (character === ";" && depth === 0) preludeStart = index + 1
  }
  if (depth !== 0) throw new Error("Unbalanced braces in web stylesheet")
  return out
}

function declarations(body) {
  const result = {}
  for (const part of body.split(";")) {
    const match = /^\s*--([a-z0-9-]+)\s*:\s*([\s\S]+?)\s*$/i.exec(part)
    if (match) result[match[1]] = match[2].replace(/\s+/g, " ")
  }
  return result
}

function resolveTokens(raw) {
  const resolved = {}
  const visit = (name, seen) => {
    if (name in resolved) return resolved[name]
    if (seen.has(name)) throw new Error(`Circular CSS variable --${name}`)
    if (!(name in raw)) throw new Error(`Undefined CSS variable --${name}`)
    seen.add(name)
    resolved[name] = raw[name].replace(/var\(--([a-z0-9-]+)\)/gi, (_, inner) => visit(inner, seen))
    return resolved[name]
  }
  for (const name of Object.keys(raw)) visit(name, new Set())
  return resolved
}

// Declarations may drop spaces around ":"; selectors and media queries must keep them
// (".a :not(.b)" is a descendant selector, ".a:not(.b)" is not).
const minifyDeclarations = text => text.replace(/\s+/g, " ").replace(/\s*([{};:,>])\s*/g, "$1").trim()
const minifyPrelude = text => text.replace(/\s+/g, " ").replace(/\s*([,>])\s*/g, "$1").trim()

function readerRules(list) {
  const kept = []
  for (const { prelude, body } of list) {
    if (prelude.startsWith("@media")) {
      const inner = readerRules(blocks(body))
      if (inner.length) kept.push(`${minifyPrelude(prelude)}{${inner.join("")}}`)
    } else if (!prelude.startsWith("@") && prelude.split(",").every(selector => READER_SELECTOR.test(selector.trim()))) {
      kept.push(`${minifyPrelude(prelude)}{${minifyDeclarations(body)}}`)
    }
  }
  return kept
}

function buildTheme(css) {
  const list = blocks(stripComments(css))
  const root = list.find(block => block.prelude === ":root")
  if (!root) throw new Error("Web stylesheet has no :root block")
  const tokens = resolveTokens(declarations(root.body))
  for (const required of ["paper", "ink", "panel", "edge", "text", "muted", "faint", "accent", "active", "completed", "archived", "danger", "tag", "display", "body", "mono"]) {
    if (!(required in tokens)) throw new Error(`Web stylesheet is missing --${required}`)
  }
  return { tokens, readerCss: `:root{${minifyDeclarations(root.body)}}${readerRules(list).join("")}` }
}

function renderModule(theme) {
  return [
    "// GENERATED by scripts/sync-web-theme.js from ../src/dashboard/style.css. Do not edit by hand.",
    "// Run `pnpm sync-theme` after changing the web stylesheet.",
    "",
    `export const webTokens = ${JSON.stringify(theme.tokens, null, 2)} as const`,
    "",
    `export const readerCss = ${JSON.stringify(theme.readerCss)}`,
    "",
  ].join("\n")
}

module.exports = { SOURCE, TARGET, buildTheme, renderModule }

if (require.main === module) {
  writeFileSync(TARGET, renderModule(buildTheme(readFileSync(SOURCE, "utf8"))))
  console.log(`Wrote ${TARGET}`)
}
